g.script:
(function(){
  var DIST=611.4, svg=document.getElementById("pa-drawer"), drawer=document.getElementById("drawer"), hint=document.getElementById("hint");
  var isOpen=false, busy=false;
  var reduce=window.matchMedia&&window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  function ease(t){ return t<.5?4*t*t*t:1-Math.pow(-2*t+2,3)/2; }
  function slide(from,to,done){ busy=true; var ms=reduce?0:520, t0=performance.now();
    (function step(now){ var t=ms?Math.min(1,(now-t0)/ms):1, y=from+(to-from)*ease(t);
      drawer.setAttribute("transform","translate(0 "+y.toFixed(1)+")");
      if(t<1) requestAnimationFrame(step); else { busy=false; if(done) done(); } })(t0); }
  function open(){ if(busy||isOpen) return; isOpen=true; hint.setAttribute("opacity","0");
    drawer.removeAttribute("visibility"); slide(DIST,0); }
  function close(){ if(busy||!isOpen) return; isOpen=false;
    slide(0,DIST,function(){ drawer.setAttribute("visibility","hidden"); }); }
  function flash(){ var sel=isOpen?"#drawer .flash":"#viewport > .hot .flash", f=svg.querySelectorAll(sel);
    for(var k=0;k<f.length;k++){ (function(r){ r.setAttribute("fill-opacity","0.16"); r.setAttribute("stroke-opacity","1");
      setTimeout(function(){ r.setAttribute("fill-opacity","0"); r.setAttribute("stroke-opacity","0"); },700); })(f[k]); } }
  var hs=svg.querySelectorAll(".hot");
  for(var j=0;j<hs.length;j++){ hs[j].addEventListener("click",function(e){ e.stopPropagation();
    if(this.getAttribute("data-act")==="open") open(); else close(); }); }
  document.getElementById("viewport").addEventListener("click",function(){ if(!busy) flash(); });
  svg.addEventListener("keydown",function(e){
    if(e.key==="ArrowUp"||e.key==="ArrowRight"||e.key==="Enter"){ e.preventDefault(); isOpen?close():open(); }
    else if(e.key==="ArrowDown"||e.key==="ArrowLeft"||e.key==="Escape"){ e.preventDefault(); if(isOpen) close(); } });
  var shown=false;
  function intro(){ if(shown) return; shown=true; hint.setAttribute("opacity","1"); setTimeout(flash,600);
    setTimeout(function(){ hint.setAttribute("opacity","0"); },3200); }
  try{ new IntersectionObserver(function(es){ if(es[0].isIntersecting&&es[0].intersectionRatio>.5) intro(); },{threshold:[.5]}).observe(svg); }
  catch(_){ setTimeout(intro,600); }
})();
